init_extra_setup_c:
const struct device *spi_dev = device_get_binding(bus_name);
if (spi_dev == NULL) { return DRIVERGEN_EVAL_ERR_INVALID; }
struct spi_dt_spec spi_cfg = {
    .bus = spi_dev,
    .config = {
        .frequency = 104000000,
        .operation = SPI_OP_MODE_MASTER | SPI_TRANSFER_MSB | SPI_WORD_SET(8),
        .slave = 0,
        .cs = { .gpio = GPIO_DT_SPEC_GET(DT_NODELABEL(spi1), cs_gpios) }
    }
};
